=== AeroRing
public class AeroRing : MonoBehaviour
{
	private static GameObject prefab;
	public static ParticleSystemOverride effectOverride = new ParticleSystemOverride
	{
		startSize = 4.5f
	};
	public Sprite largeSprite;
	public SpriteRenderer spriteRenderer;
	private static Vector2[] atkVecArr;
	private static Quaternion[] atkQuatArr;
	public Transform ringEmitterTrans;
	public Transform ringMainEmitterTrans;
	public ParticleEffect ringEmitterEffect;
	public Attack attack;
	public CircleCollider2D attackCol;
	private Transform parentTrans;
	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(2f);
	private bool resetQueued;
	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.3f);
	private ChaosQuickStopwatch animStopwatch = new ChaosQuickStopwatch(0.075f);
	private int maxIndex = 6;
	private int currentIndex;
	private AudioSource loopAudio;
	private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch();
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/AeroRing.prefab"));
	public void Init(Transform givenTrans, string givenCat, string givenID, bool givenEmp)
	{
		parentTrans = givenTrans;
		if (givenEmp)
		{
			animStopwatch.SetDelay(0.05f);
			atkStopwatch.SetDelay(0.25f);
			attackCol.radius = 2.5f;
			attack.SetAttackInfo(givenCat, givenID, 2);
			spriteRenderer.sprite = largeSprite;
			ringEmitterTrans.localScale = new Vector3(1.5f, 1.5f, 1f);
			ringMainEmitterTrans.localScale = new Vector3(1.25f, 1.25f, 1f);
			ParticleEffect particleEffect = ringEmitterEffect;
			float? emissionRate = 40f;
			ParticleSystemOverride overrides = effectOverride;
			particleEffect.Play(emissionRate, null, overrides);
		}
		else
		{
			attack.SetAttackInfo(givenCat, givenID);
			ringEmitterEffect.Play(20f);
		}
	}
	private void Awake()
	{
		if (atkVecArr == null)
		{
			atkVecArr = new Vector2[maxIndex];
			atkQuatArr = new Quaternion[maxIndex];
			for (int i = 0; i < maxIndex; i++)
			{
				ref Vector2 reference = ref atkVecArr[i];
				reference = Globals.GetCirclePositionVector(maxIndex, i);
				ref Quaternion reference2 = ref atkQuatArr[i];
				reference2 = Globals.GetRotationQuaternion(atkVecArr[i]);
			}
		}
	}
	private void Start()
	{
		lifeStopwatch.IsRunning = true;
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 80;
		float scale = 0.25f;
		Vector3? emitPosition = transform.position - Vector3.up * 1.5f;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		SoundManager.PlayAudioWithDistance("TornadoStart", transform.position, null, 24f, 0.1f);
		CameraController.ShakeCamera(0.25f);
		PlayLoopAudio();
	}
	private void Update()
	{
		if (resetQueued)
		{
			return;
		}
		if (!lifeStopwatch.IsRunning)
		{
			Reset();
			return;
		}
		if (!animStopwatch.IsRunning)
		{
			animStopwatch.IsRunning = true;
			currentIndex = (currentIndex + 1) % maxIndex;
		}
		PlayLoopAudio();
	}
	private void FixedUpdate()
	{
		if (!resetQueued && !atkStopwatch.IsRunning)
		{
			atkStopwatch.IsRunning = true;
			attackCol.enabled = false;
			attackCol.enabled = true;
		}
	}
	private void LateUpdate()
	{
		if (parentTrans != null)
		{
			transform.position = parentTrans.position;
		}
	}
	public void Reset()
	{
		if (!resetQueued)
		{
			resetQueued = true;
			parentTrans = null;
			attackCol.gameObject.SetActive(value: false);
			Vector2 vector = transform.position;
			PoolManager.GetPoolItem<ParticleEffect>("WindBurstEffect").Emit(5, vector);
			ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("WindTwirlEffect");
			int? particleCount = 1;
			Vector3? position = vector;
			Vector3? localEulerAngles = new Vector3(0f, 0f, 33f);
			poolItem.Emit(particleCount, position, null, localEulerAngles);
			ParticleEffect poolItem2 = PoolManager.GetPoolItem<ParticleEffect>("WindTwirlEffect");
			particleCount = 1;
			localEulerAngles = vector;
			position = new Vector3(0f, 0f, -33f);
			poolItem2.Emit(particleCount, localEulerAngles, null, position);
			DustEmitter poolItem3 = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount2 = 80;
			float scale = 0.25f;
			position = vector - Vector2.up * 1.5f;
			poolItem3.EmitCircle(particleCount2, scale, -1f, -1f, position);
			if (loopAudio != null && loopAudio.isPlaying)
			{
				loopAudio.Stop();
				SoundManager.PlayAudioWithDistance("WindBlastSharp", vector, null, 24f, 0.1f);
			}
			Object.Destroy(gameObject);
		}
	}
	private void PlayLoopAudio()
	{
		if (!audioStopwatch.IsRunning)
		{
			audioStopwatch.IsRunning = true;
			string audioID = "TornadoLoop";
			Transform originTrans = transform;
			loopAudio = SoundManager.PlayAudioWithDistance(audioID, null, originTrans, 24f, 0.0625f, 1.25f);
		}
	}
}
