=== AeroRipple
public class AeroRipple : Projectile
{
	private static GameObject prefab;
	private float initKBMulti;
	private float lerpValue;
	private bool lerpCompleted;
	private bool fadeCalled;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/AeroRipple.prefab"));
	public override void Start()
	{
		base.Start();
		if (attackBox.atkInfo != null)
		{
			initKBMulti = attackBox.atkInfo.knockbackMultiplier;
		}
	}
	public override void ResetProjectile()
	{
		if (!fadeCalled)
		{
			fadeCalled = true;
			flyStopwatchID = ChaosStopwatch.Begin(0.25f);
			anim.Play("Fade", -1, 0f);
			moveSpeed *= 0.125f;
		}
		else
		{
			base.ResetProjectile();
		}
	}
	private void LateUpdate()
	{
		if (!lerpCompleted)
		{
			lerpValue = Mathf.Pow(1f - ChaosStopwatch.GetTimePercentage(flyStopwatchID), 3f) - 0.125f;
			if (attackBox != null && attackBox.atkInfo != null)
			{
				attackBox.atkInfo.knockbackMultiplier = Mathf.Lerp(0f, initKBMulti, lerpValue);
			}
			lerpCompleted = lerpValue <= 0f;
		}
	}
}
=== AirChannel
public class AirChannel : MonoBehaviour
{
	private static GameObject prefab;
	public Attack attack;
	public BoxCollider2D attackBoxCol;
	private const float attackRange = 5.5f;
	private static Vector2 localStartVector = Vector2.zero;
	private static Vector2 localEndVector = new Vector2(0f, 5.5f);
	[HideInInspector]
	public Vector2 targetVector;
	private Vector2 currentPosition;
	private Vector2 targetPosition;
	public float atkDuration = 0.2f;
	private int atkStopwatchID;
	private float rangePercentage;
	private bool atkComplete;
	private float lerpValue;
	private Vector3 moveVector;
	public bool useShockwaveEffect;
	private int shockwaveTimer = -1;
	private float shockwaveInterval = 0.05f;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/AirChannel.prefab"));
	private void Awake()
	{
		attack.knockbackMultiplierOverride = 45f;
	}
	private void Start()
	{
		atkStopwatchID = ChaosStopwatch.Begin(atkDuration);
		currentPosition = transform.position;
		targetPosition = currentPosition + targetVector * 5.5f;
		targetPosition = Globals.GetLinecastVector(currentPosition, targetPosition, ChaosCollisions.layerUpperWallAndObst);
		rangePercentage = Vector2.Distance(currentPosition, targetPosition) / 5.5f;
		SoundManager.PlayAudioWithDistance("WindBlastSharp", transform.position);
		moveVector = (currentPosition - targetPosition).normalized;
		if (useShockwaveEffect)
		{
			PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail").Emit(currentPosition, (Vector3)currentPosition + -moveVector * 5f, -1, emitEveryOther: false, -1f, snapToFit: true, 0.3f);
		}
	}
	private void Update()
	{
		if (!atkComplete && useShockwaveEffect && ChaosStopwatch.Check(shockwaveTimer))
		{
			ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave");
			int? particleCount = 1;
			Vector3? position = attackBoxCol.transform.position;
			Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
			poolItem.Emit(particleCount, position, null, localEulerAngles);
			shockwaveTimer = ChaosStopwatch.Begin(shockwaveInterval);
		}
	}
	private void FixedUpdate()
	{
		if (!atkComplete)
		{
			lerpValue = ChaosStopwatch.GetTimePercentage(atkStopwatchID);
			attack.knockbackMultiplierOverride = Mathf.Lerp(45f, 15f, lerpValue);
			if (lerpValue <= rangePercentage)
			{
				attackBoxCol.transform.localPosition = Vector2.Lerp(localEndVector, localStartVector, 1f - lerpValue * lerpValue);
			}
			if (lerpValue >= 1f)
			{
				atkComplete = true;
				attackBoxCol.enabled = false;
				Object.Destroy(gameObject, 1f);
			}
		}
	}
}
