=== AirSentry
public class AirSentry : Projectile
{
	private static GameObject prefab;
	private static Vector3 thinScale = new Vector3(0.75f, 1f, 1f);
	public Transform sentryContainer;
	public GameObject sentryTemplate;
	private GameObject[] sentryObjArr;
	private Vector3 sentryPos;
	private int sentryCount = 10;
	private string skillCat = string.Empty;
	private string skillID = string.Empty;
	private List<GameObject> targetList;
	private List<GameObject> ignoreList;
	private ChaosQuickStopwatch targetStopwatch = new ChaosQuickStopwatch(0.1f);
	private TargetInfo currentInfo;
	private Arrow currentArrow;
	private Vector2 atkVector;
	private ParticleEffect shootEffect;
	private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.08f);
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/AirSentry.prefab"));
	public void Init(List<GameObject> givenList, string givenCat, string givenID, int givenCount)
	{
		ignoreList = givenList;
		skillCat = givenCat;
		skillID = givenID;
		sentryCount = givenCount;
	}
	public override void Start()
	{
		base.Start();
		Vector2 vector = transform.position;
		sentryObjArr = new GameObject[sentryCount];
		sentryObjArr[0] = sentryTemplate;
		for (int i = 1; i < sentryCount; i++)
		{
			atkVector = Globals.GetCirclePositionVector(sentryCount, i);
			sentryObjArr[i] = Object.Instantiate(sentryTemplate, vector + atkVector * 0.75f, Globals.GetRotationQuaternion(atkVector), sentryContainer);
		}
		sentryObjArr.Shuffle();
	}
	public override void Update()
	{
		base.Update();
		PlayAudio();
		if (targetStopwatch.IsRunning)
		{
			return;
		}
		targetStopwatch.IsRunning = true;
		targetList = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, 8f, playerTagOnly: false, ignoreList, parentObject, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
		if (targetList.Count == 0)
		{
			return;
		}
		shootEffect = PoolManager.GetPoolItem<ParticleEffect>("SpinningCircleBurst");
		int num = Random.Range(1, 3);
		while (num >= 0 && targetList.Count != 0)
		{
			currentInfo = Entity.GetTargetInfoFromObject(targetList[0]);
			targetList.RemoveAt(0);
			if (currentInfo != null)
			{
				sentryCount--;
				if (sentryObjArr[sentryCount] != null)
				{
					sentryPos = sentryObjArr[sentryCount].transform.position;
					sentryObjArr[sentryCount].SetActive(value: false);
				}
				else
				{
					sentryPos = transform.position;
				}
				CreateArrow(sentryPos, (currentInfo.hurtBoxPosition - sentryPos).normalized);
				if (sentryCount <= 0)
				{
					ResetProjectile();
					break;
				}
			}
			num--;
		}
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (sentryContainer != null)
		{
			sentryContainer.Rotate(rotationVector * Time.fixedDeltaTime);
		}
	}
	public override void ResetProjectile()
	{
		base.ResetProjectile();
		sentryPos = transform.position;
		WindBurst.CreateBurst(sentryPos, string.Empty, string.Empty, 1, 1.5f);
		PoolManager.GetPoolItem<ParticleEffect>("WindTwirlSmallEffect").Emit(1, sentryPos);
		for (int i = 0; i < sentryCount; i++)
		{
			CreateArrow(sentryPos, Random.insideUnitCircle.normalized);
		}
	}
	private void CreateArrow(Vector2 givenPosition, Vector2 givenVector)
	{
		currentArrow = (Arrow)Projectile.CreateProjectile(parentEntity, Arrow.Prefab, givenPosition, Globals.GetRotationQuaternion(givenVector));
		currentArrow.attackBox.SetAttackInfo(skillCat, skillID);
		currentArrow.attackBox.knockbackOverwriteVector = givenVector;
		currentArrow.moveVector = givenVector;
		currentArrow.moveSpeed = 32f;
		currentArrow.flyTime = 0.25f;
		currentArrow.disableOnHit = false;
		currentArrow.transform.localScale = thinScale;
		SoundManager.PlayWithDistAndSPR("WindSnap", givenPosition, 1.25f);
		if (shootEffect != null)
		{
			shootEffect.Emit(1, givenPosition, localEulerAngles: Globals.GetRotationVector(givenVector), overrides: ParticleEffectOverrides.StartLifeTime0p2);
		}
	}
	private void PlayAudio()
	{
		if (!audioStopwatch.IsRunning)
		{
			audioStopwatch.IsRunning = true;
			SoundManager.PlayAudioWithDistance("WindCircle", transform.position, null, 24f, -1f, 1.25f);
		}
	}
}
=== AirSlideTrap
public class AirSlideTrap : MonoBehaviour
{
	private static GameObject _prefab;
	private static AudioSource windAudio;
	private static int audioStopwatchID;
	public Animator anim;
	public Attack attack;
	public CircleCollider2D atkCollider;
	public SpriteRenderer circleSprite;
	public SpriteRenderer trapSprite;
	private float lifeTime = 2.5f;
	private float primeTime = 0.5f;
	private float blastRadius = 1.25f;
	private int lifeStopwatchID;
	private int primeStopwatchID;
	private bool primed;
	private bool detonated;
	private Vector2 blastPos;
	private Vector2 atkVec;
	private Vector3 atkRoteVec;
	private string skillCat;
	private string skillID;
	private bool skillEmp;
	private Entity parentEnt;
	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/AirSlideTrap.prefab");
			}
			return _prefab;
		}
	}
	public void Initialize(string givenCat, string givenID, Vector2 givenVec, bool givenEmp, Entity givenEnt)
	{
		skillCat = givenCat;
		skillID = givenID;
		parentEnt = givenEnt;
		attack.SetAttackInfo(skillCat, skillID, 3);
		atkVec = givenVec;
		atkRoteVec = Globals.GetRotationVector(atkVec);
		trapSprite.transform.localEulerAngles = atkRoteVec;
		skillEmp = givenEmp;
		if (skillEmp)
		{
			lifeTime = 4f;
			primeTime = 0.3f;
			blastRadius = 1.75f;
		}
		WindBurst.CreateBurst(transform.position + Vector3.up * 0.9f, string.Empty, string.Empty);
	}
	private void Start()
	{
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		primeStopwatchID = ChaosStopwatch.Begin(primeTime);
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(Detonate));
		Attack attack2 = this.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(Detonate));
		atkCollider.radius = blastRadius;
		circleSprite.transform.localScale = new Vector3(blastRadius * 0.25f, blastRadius * 0.25f, 1f);
		SoundManager.PlayWithDistAndSPR("WindArrowStart", transform.position);
	}
	private void Update()
	{
		if (detonated)
		{
			return;
		}
		if (ChaosStopwatch.Check(lifeStopwatchID))
		{
			Detonate();
			return;
		}
		if (!primed)
		{
			if (!ChaosStopwatch.Check(primeStopwatchID))
			{
				return;
			}
			primed = true;
			anim.Play("Idle", -1, 0f);
			atkCollider.enabled = true;
		}
		HandleAudio();
	}
	private void Detonate(Entity givenEnt = null)
	{
		if (!detonated)
		{
			detonated = true;
			anim.Play("Detonate", -1, 0f);
			Attack attack = this.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(Detonate));
			blastPos = transform.position;
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 20;
			float scale = 0.25f;
			Vector3? emitPosition = blastPos;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			blastPos += Vector2.up * 0.9f;
			if (givenEnt != null)
			{
				CreateVacuumShot();
			}
			PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave").Emit(1, blastPos, localEulerAngles: atkRoteVec, overrides: ParticleEffectOverrides.StartColorAlpha0p25);
			PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave").Emit(1, blastPos + atkVec, localEulerAngles: atkRoteVec, overrides: ParticleEffectOverrides.StartColorAlpha0p25);
			HandleAudio(status: false);
			SoundManager.PlayWithDistAndSPR("WindArrowStart", blastPos);
			if (gameObject != null)
			{
				UnityEngine.Object.Destroy(gameObject, 0.25f);
			}
		}
	}
	private void HandleAudio(bool status = true)
	{
		if (status)
		{
			if (windAudio == null || ChaosStopwatch.Check(audioStopwatchID))
			{
				audioStopwatchID = ChaosStopwatch.Begin(0.25f);
				windAudio = SoundManager.PlayWithDistAndSPR("WindCircle", transform.position);
			}
		}
		else if (windAudio != null)
		{
			windAudio.Stop();
			windAudio = null;
		}
	}
	private void CreateVacuumShot()
	{
		VacuumShot vacuumShot = (VacuumShot)Projectile.CreateProjectile(parentEnt, VacuumShot.Prefab, blastPos, Globals.GetRotationQuaternion(atkVec));
		vacuumShot.attackBox.SetAttackInfo(skillCat, skillID);
		vacuumShot.moveVector = atkVec;
		vacuumShot.transform.localScale *= ((!skillEmp) ? 1.25f : 1.75f);
